INSERT INTO ai_message (id, ai_conversation_id, sequence_no, role, content, generated_sql, created_at)
VALUES (5, 3, 1, 'USER', '라인별 생산 계획 수량을 알려 줘.', NULL, '2026-11-13 09:10:00'),
       (6, 3, 2, 'ASSISTANT', '생산 계획 수량을 라인별로 합산했습니다. 포장완료 전 작업도 계획에는 포함됩니다.', 'SELECT l.line_name, SUM(p.quantity) AS planned_quantity FROM production_plan p JOIN work_order w ON w.id = p.work_order_id JOIN line l ON l.id = w.line_id GROUP BY l.line_name ORDER BY l.id', '2026-11-13 09:10:00');

